mapper.select:
SELECT * FROM booking
WHERE user_id = #{userId}
ORDER BY requested_at DESC

mapper.insert:
INSERT INTO booking (
    id, user_id, lesson_id, availability_id, title, requested_at, memo
) VALUES (
    UUID(), #{userId}, #{lessonId}, #{availabilityId}, #{title}, NOW(), #{memo}
)

mapper.update:
UPDATE booking
SET title = #{title}, memo = #{memo}
WHERE id = #{id}

UPDATE booking
SET confirmed_at = NOW()
WHERE id = #{id}

UPDATE booking
SET canceled_at = NOW()
WHERE id = #{id}

UPDATE booking
SET done_at = NOW()
WHERE id = #{id}
